/// <summary>
/// Applies stock adjustments, makes reorder decisions, allocates zones and
/// places supplier orders.
/// </summary>
public sealed class StockController
{
    // adjustments
    private readonly List<string> _movements = new();
    // reorder
    private readonly Dictionary<string, int> _reorderThresholds = new(StringComparer.Ordinal);
    private readonly int _defaultReorder = 20;
    // zone allocation
    private readonly Dictionary<string, int> _zoneUsage = new(StringComparer.Ordinal);
    // supplier ordering
    private readonly ISupplier _supplier;
    private readonly Dictionary<string, int> _pending = new(StringComparer.Ordinal);

    public StockController(ISupplier supplier) => _supplier = supplier;

    // ---- adjustments ----

    public int AdjustStock(StockItem item, int delta)
    {
        if (delta == 0)
            return item.OnHand;
        if (delta < 0 && item.OnHand + delta < 0)
            return item.OnHand;
        item.OnHand += delta;
        if (delta > 0)
            _movements.Add($"IN {item.Sku} {delta}");
        else
            _movements.Add($"OUT {item.Sku} {-delta}");
        if (item.OnHand < item.Reserved)
            _movements.Add($"WARN {item.Sku} oversold");
        return item.OnHand;
    }

    public int Available(StockItem item)
    {
        int free = item.OnHand - item.Reserved;
        if (free < 0)
            return 0;
        return free;
    }

    public int MovementCount => _movements.Count;

    // ---- reorder ----

    public bool NeedsReorder(StockItem item)
    {
        if (item.Sku.Length == 0)
            return false;
        int available = item.OnHand - item.Reserved;
        var threshold = ResolveThreshold(item.Sku);
        if (item.ReorderPoint > 0)
            return available <= item.ReorderPoint;
        return available <= threshold;
    }

    public int ReorderQuantity(StockItem item)
    {
        if (!NeedsReorder(item))
            return 0;
        int available = item.OnHand - item.Reserved;
        int target = item.ReorderPoint > 0 ? item.ReorderPoint * 2 : _defaultReorder * 2;
        int qty = target - available;
        if (qty < 0)
            qty = 0;
        else if (qty < 5)
            qty = 5;
        return qty;
    }

    public int ResolveThreshold(string sku)
    {
        if (string.IsNullOrEmpty(sku))
            return _defaultReorder;
        if (_reorderThresholds.TryGetValue(sku, out var t))
            return t;
        return _defaultReorder;
    }

    // ---- zone allocation ----

    public string AllocateToZone(StockItem item, Warehouse warehouse)
    {
        if (warehouse.Zones.Count == 0)
            return "no zones";
        int need = item.OnHand - item.Reserved;
        if (need <= 0)
            return "nothing to place";
        foreach (var zone in warehouse.Zones)
        {
            var used = _zoneUsage.TryGetValue(zone.Name, out var u) ? u : 0;
            int spare = zone.Capacity - used;
            if (spare <= 0)
                continue;
            int place = need > spare ? spare : need;
            _zoneUsage[zone.Name] = used + place;
            need -= place;
            if (need <= 0)
                return $"placed in {zone.Name}";
        }
        return "overflow";
    }

    public int ZoneSpare(Warehouse warehouse)
    {
        int spare = 0;
        foreach (var zone in warehouse.Zones)
        {
            var used = _zoneUsage.TryGetValue(zone.Name, out var u) ? u : 0;
            if (zone.Capacity > used)
                spare += zone.Capacity - used;
        }
        return spare;
    }

    // ---- supplier ordering ----

    public bool PlaceReorder(StockItem item)
    {
        var qty = ReorderQuantity(item);
        if (qty <= 0)
            return false;
        if (_pending.TryGetValue(item.Sku, out var existing) && existing >= qty)
            return false;
        var accepted = _supplier.PlaceOrder(item.Sku, qty);
        if (accepted)
            _pending[item.Sku] = qty;
        return accepted;
    }

    public bool ConfirmDelivery(StockItem item, int delivered)
    {
        if (delivered <= 0)
            return false;
        if (!_pending.TryGetValue(item.Sku, out var qty))
            return false;
        item.OnHand += delivered;
        if (delivered >= qty)
            _pending.Remove(item.Sku);
        else
            _pending[item.Sku] = qty - delivered;
        return true;
    }

    public string Classify(StockItem item)
    {
        int available = item.OnHand - item.Reserved;
        if (available < 0)
            return "oversold";
        if (available == 0)
            return "out";
        if (item.ReorderPoint > 0 && available <= item.ReorderPoint)
            return "low";
        else if (available > item.ReorderPoint * 5)
            return "excess";
        return "ok";
    }

    public IReadOnlyList<string> AuditStock(StockItem item, Warehouse warehouse)
    {
        var findings = new List<string>();
        if (item.OnHand < 0)
            findings.Add($"{item.Sku}:negative-onhand");
        if (item.Reserved < 0)
            findings.Add($"{item.Sku}:negative-reserve");
        if (item.OnHand < item.Reserved)
            findings.Add($"{item.Sku}:oversold");
        foreach (var zone in warehouse.Zones)
        {
            var used = _zoneUsage.TryGetValue(zone.Name, out var u) ? u : 0;
            if (used > zone.Capacity)
                findings.Add($"{zone.Name}:over-capacity");
            else if (used < 0)
                findings.Add($"{zone.Name}:negative-usage");
        }
        if (findings.Count == 0)
            findings.Add("clean");
        return findings;
    }

    public int ForecastDepletion(StockItem item, int dailyDemand)
    {
        if (dailyDemand <= 0)
            return -1;
        int available = item.OnHand - item.Reserved;
        if (available <= 0)
            return 0;
        int days = available / dailyDemand;
        if (item.ReorderPoint > 0 && available <= item.ReorderPoint)
            return 0;
        if (days > 365)
            return 365;
        var threshold = ResolveThreshold(item.Sku);
        if (threshold > 0 && available <= threshold)
            return 1;
        else if (days < 7)
            return days;
        return days;
    }
}

